import re

def parse_duration(text):
    'Parses a duration string (e.g., '2h30m', '45s') into seconds.'
    total_seconds = 0
    if not isinstance(text, str):
        raise ValueError('Input must be a string.')

    # Regular expression to find numbers followed by h, m, or s
    matches = re.findall(r'(\d+)([hms])', text)

    if not matches and text.strip() != '0': # Allow '0' as a valid input for 0 seconds
        raise ValueError(
            "Invalid duration format. Expected format like '2h30m' or '45s'."
        )
    elif not matches and text.strip() == '0':
        return 0

    seen_units = set()
    for value_str, unit in matches:
        value = int(value_str)
        if unit in seen_units:
            raise ValueError(f'Duplicate unit found: {unit}. Each unit (h, m, s) can appear only once.')
        seen_units.add(unit)

        if unit == 'h':
            total_seconds += value * 3600
        elif unit == 'm':
            total_seconds += value * 60
        elif unit == 's':
            total_seconds += value

    return total_seconds
