def chunk_iterable(items, size):
    'Yields fixed-size chunks from an iterable.'
    if size <= 0:
        raise ValueError('Chunk size must be positive')

    iterator = iter(items)
    while True:
        chunk = []
        try:
            for _ in range(size):
                chunk.append(next(iterator))
            yield chunk
        except StopIteration:
            if chunk:  # Yield any remaining items
                yield chunk
            break
