import functools

def lru_cache_decorator(maxsize):
    '''
    A simple LRU cache decorator.

    Args:
        maxsize (int): The maximum number of items to store in the cache.
                       If maxsize is None, the cache is unbounded.
                       If maxsize is 0, the cache is disabled.
    '''
    def decorator(func):
        if maxsize is None:  # Unbounded cache
            cache = {}
            hits = 0
            misses = 0

            @functools.wraps(func)
            def wrapper(*args, **kwargs):
                nonlocal hits, misses
                key = tuple(args) + tuple(sorted(kwargs.items()))
                if key in cache:
                    hits += 1
                    return cache[key]
                else:
                    misses += 1
                    result = func(*args, **kwargs)
                    cache[key] = result
                    return result

            def cache_info():
                return f'CacheInfo(hits={hits}, misses={misses}, maxsize={maxsize}, currsize={len(cache)})'

            def cache_clear():
                nonlocal hits, misses, cache
                cache = {}

